import {canMutateCoastalSnapshot,saveCoastalSnapshot,readCoastalSnapshot,deleteCoastalSnapshot} from './coastal-offline-core.js';
import {formatBytes} from './offline-core.js';
/** Existing Guide owns the offline controls; overview replacement remounts this same section. */
export function initCoastalOffline(){
 let root=null,alive=true,request=null,generation=0;
 const create=()=>{if(!alive||root?.isConnected)return;const guide=document.getElementById('guide-panel');if(!guide)return;
 generation++;request?.abort();root=document.createElement('details');const mounted=root;root.className='guide-topic';root.id='coastal-offline';
 root.innerHTML='<summary>Coastal readings offline</summary><p>Save the original public SLO report, surface currents and measured history on this device. Outside SLO report coverage these remain labelled references. Terrain, imagery and habitat publication proof are not included. Original source expiry still applies.</p><div class="install-actions"><button type="button" data-save>Save coastal readings</button><button type="button" data-cancel hidden>Cancel</button><button type="button" data-delete disabled>Delete saved readings</button></div><p role="status" data-status></p><ul data-products></ul>';
 guide.append(root);const status=root.querySelector('[data-status]'),products=root.querySelector('[data-products]'),save=root.querySelector('[data-save]'),cancel=root.querySelector('[data-cancel]'),remove=root.querySelector('[data-delete]');
 const writable=canMutateCoastalSnapshot({caches:globalThis.caches});save.disabled=!writable;
 const current=()=>alive&&root===mounted&&mounted.isConnected;
 async function show(){const gen=generation;try{const meta=await readCoastalSnapshot({origin:location.origin,caches:globalThis.caches});if(!current()||gen!==generation)return;products.replaceChildren();remove.disabled=!writable;if(!meta){status.textContent='No coastal readings saved. Chart trip packs are managed separately.'+(!writable?' Safe saving is unavailable in this browser; existing snapshots remain readable.':'');return;}status.textContent=`Saved ${new Date(meta.saved_at).toLocaleString()} · ${formatBytes(meta.bytes)}. Saved time is distinct from original source times.${!writable?' Safe save/delete is unavailable in this browser.':''}`;for(const product of meta.products){const item=document.createElement('li');item.textContent=`${product.path.split('/').at(-1)} · ${formatBytes(product.bytes)} · source assembled ${product.generated_at}`;products.append(item);}}catch{if(current()&&gen===generation){save.disabled=true;remove.disabled=true;status.textContent='Offline storage is unavailable. Online readings remain usable.';}}}
 save.addEventListener('click',async()=>{const gen=++generation;request?.abort();request=new AbortController();save.disabled=true;remove.disabled=true;cancel.hidden=false;status.textContent='Saving the three public snapshots…';try{await saveCoastalSnapshot({origin:location.origin,caches:globalThis.caches,signal:request.signal});if(gen===generation&&current())await show();}catch(error){if(gen===generation&&current()){if(error?.committed){await show();status.textContent+=' New readings saved; obsolete snapshot cleanup failed. Use Delete saved readings to clear them.';}else status.textContent=request.signal.aborted?'Save cancelled. Previous saved readings are unchanged.':'Save failed. Previous saved readings are unchanged; check connection or storage.';}}finally{if(gen===generation&&current()){save.disabled=false;cancel.hidden=true;remove.disabled=!writable;}}});
 cancel.addEventListener('click',()=>request?.abort());remove.addEventListener('click',async()=>{const gen=++generation;save.disabled=true;remove.disabled=true;try{await deleteCoastalSnapshot({origin:location.origin,caches:globalThis.caches});if(gen===generation&&current())await show();}catch{if(gen===generation&&current())status.textContent='Saved readings could not be deleted. Offline storage may be unavailable.';}finally{if(gen===generation&&current()){save.disabled=!writable;remove.disabled=!writable;}}});void show();
 };
 create();const observer=new MutationObserver(create),guide=document.getElementById('guide-panel');if(guide)observer.observe(guide,{childList:true});
 const destroy=()=>{alive=false;generation++;request?.abort();observer.disconnect();};window.addEventListener('pagehide',destroy,{once:true});return {destroy};
}
